#include <iostream>

int main() {
    float cd = 0.0f;
    float cr = 0.0f;

    // In loi nhac va nhan du lieu
    std::cout << "Hay nhap chieu dai: ";
    std::cin >> cd;
    std::cout << "Va nhap chieu rong: ";
    std::cin >> cr;

    // Tinh toan va in ket qua truc tiep tren luong cout
    std::cout << "Dien tich = " << (cd * cr) << '\n';
    std::cout << "Chu vi = " << (2.0f * (cd + cr)) << '\n';

    return 0;
}
